/**
 * earth-elevation-1deg — coarse global land-elevation grid for the planetary relief + blanket.
 *
 * Source: three-globe earth-topology bump map (relief) masked to land by earth-water (both MIT;
 * derived from NASA Blue Marble / public-domain topography). Resampled to a 360×180 (1°)
 * equirectangular grid; OCEAN = 0, LAND = 2..255 (floor 2 so even flat sea-level land is
 * distinguishable from ocean — the blanket needs the land mask, not just peaks). Row 0 = lat
 * +90 (north), col 0 = lon -180. Consumed by scene-planetary.js (golden-angle relief spikes +
 * the hypsometric land blanket). Relative height, not metres.
 */
export const ELEV_W = 360;
export const ELEV_H = 180;
export const ELEV_B64 = '';
